import math
from collections import Counter
def ent(s):
    c=Counter(s); n=len(s)
    return -sum(v/n*math.log2(v/n) for v in c.values())
def balanced(alphabet, n):
    # distribute n chars over alphabet as evenly as possible
    s=""
