import math, random, string
from collections import Counter
def ent(s):
    c=Counter(s); n=len(s)
    return -sum(v/n*math.log2(v/n) for v in c.values())
def test(s):
    rc,out,err=run([s],["--additional-pattern",'(.*)'])
    return bool(out.strip())
A=string.ascii_uppercase+string.digits
def build(counts, alphabet, seed=0):
    s="".join("".join(c*v for c,v in zip(alphabet,counts)))
    l=list(s); random.Random(seed).shuffle(l); return "".join(l)
counts=[2]*10+[1]*10
alphabets={
 "seq20":A[:20],
 "rand20letters":random.Random(7).sample(string.ascii_uppercase,20),
 "rand20mix":random.Random(8).sample(A,20),
 "digits20":string.digits*2,
 "lower20":string.ascii_lowercase[:20],
 "seq20rev":A[19::-1],
}
for name,al in alphabets.items():
    oks=[]
    for sd in range(3):
        s=build(counts,al,sd)
        oks.append((test(s), round(ent(s),3)))
    print(f"{name:16s} {oks}")
PY"}

