import string, random, math
from collections import Counter
def parts(n, minv=1):
    if n==0: yield []
    else:
        for v in range(minv, n+1):
            for rest in parts(n-v, v): yield [v]+rest
def H(counts):
    n=sum(counts)
    return -sum(c/n*math.log2(c/n) for c in counts)
UP=string.ascii_uppercase; DI=string.digits; LO=string.ascii_lowercase
