import string, random, math
from collections import Counter
UP=string.ascii_uppercase
def parts(n, minv=1):
    if n==0: yield []
    else:
        for v in range(minv, n+1):
            for rest in parts(n-v, v): yield [v]+rest
def H(counts):
    n=sum(counts)
    return -sum(c/n*math.log2(c/n) for c in counts)
random.seed(1)
n=7
for counts in parts(n):
    e=H(counts); k=len(counts)
    if k>26: continue
    row={}
    for tag,pool in (("AZ",UP),("noZ",UP[:25])):
        acc=0
        for t in range(6):
            ch=random.sample(pool,k)
            s=list("".join(c*v for c,v in zip(ch,counts)))
            random.shuffle(s)
            h,_,_=batch(["".join(s)])
            if 1 in h: acc+=1
        row[tag]=acc
    print(f"counts={counts} u={k} ent={e:.4f}: withZpool={row['AZ']}/6 noZpool={row['noZ']}/6")
