            # tag 1 => must include Z; tag 0 => must exclude Z
            if tag==1:
                ch=random.sample([c for c in UP if c!='Z'],k-1)+['Z']
            else:
                ch=random.sample([c for c in UP if c!='Z'],k)
            for t in range(4):
                s=list("".join(c*v for c,v in zip(ch,counts)))
                random.shuffle(s)
                rows.append("".join(s)); tags.append((tag,e))
