    mins={0:[],1:[]}
    for i,(tag,e) in enumerate(tags):
        if (i+1) in hits: mins[tag].append(e)
    print(f"n={n:2d}: minent(Z)={min(mins[1],default=None)} minent(noZ)={min(mins[0],default=None)}")
