{"command": "cat > /workspace/src/ignore.go <<'GOEOF'
package main

import (
	"strings"
)

// ignorePattern is one line of a .secretsignore file.
type ignorePattern struct {
	negated  bool
	dirOnly  bool
	anchored bool
	segments []string
}

// IgnoreList holds file patterns and literal secrets to skip.
type IgnoreList struct {
	patterns []*ignorePattern
	secrets  map[string]struct{}
}

// ParseIgnoreList reads .secretsignore content.
func ParseIgnoreList(content string) *IgnoreList {
	il := &IgnoreList{secrets: make(map[string]struct{})}
	inSecrets := false
	for _, raw := range strings.Split(content, "\n") {
		line := strings.TrimRight(raw, "\r")
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			continue
		}
		if strings.HasPrefix(trimmed, "#") {
			continue
		}
		if trimmed == "[secrets]" {
			inSecrets = true
			continue
		}
		if inSecrets {
			il.secrets[trimmed] = struct{}{}
			continue
		}
		il.patterns = append(il.patterns, parsePattern(line))
	}
	return il
}

func parsePattern(line string) *ignorePattern {
	p := &ignorePattern{}
	s := strings.TrimRight(line, "\r")
	s = strings.TrimLeft(s, " \t")
	s = strings.TrimRight(s, " \t")
	if strings.HasPrefix(s, "!") {
		p.negated = true
		s = s[1:]
	}
	if strings.HasSuffix(s, "/") {
		p.dirOnly = true
		s = strings.TrimSuffix(s, "/")
	}
	if strings.HasPrefix(s, "/") {
		p.anchored = true
		s = strings.TrimPrefix(s, "/")
	}
	p.segments = splitGlob(s)
	return p
}

// splitGlob splits a glob expression on path separators, keeping glob syntax.
func splitGlob(s string) []string {
	var segs []string
	cur := strings.Builder{}
	for i := 0; i < len(s); i++ {
		if s[i] == '/' {
			segs = append(segs, cur.String())
			cur.Reset()
			continue
		}
		cur.WriteByte(s[i])
	}
	segs = append(segs, cur.String())
	return segs
}

// matchesPath reports whether the pattern matches the slash separated relative
// path. dirMode should be true when checking a directory entry.
func (p *ignorePattern) matchesPath(path string, dirMode bool) bool {
	if p.dirOnly && !dirMode {
		return false
	}
	segs := strings.Split(path, "/")
	// If the pattern contains no slash, it matches any basename.
	if len(p.segments) == 1 && !p.anchored {
		return globMatch(p.segments[0], segs[len(segs)-1])
	}
	// Anchored patterns must match from the start; unanchored may match at any
	// depth.
	start := 0
	if !p.anchored {
		start = -1
	}
	for i := 0; i < len(segs); i++ {
		if start >= 0 && i != start {
			continue
		}
		if segMatch(p.segments, segs[i:]) {
			return true
		}
	}
	return false
}

func segMatch(pat []string, segs []string) bool {
	i := 0
	j := 0
	for i < len(pat) {
		if pat[i] == "**" {
			if i == len(pat)-1 {
				return true
			}
			for k := j; k < len(segs); k++ {
				if segMatch(pat[i+1:], segs[k:]) {
					return true
				}
			}
			return false
		}
		if j >= len(segs) {
			return false
		}
		if !globMatch(pat[i], segs[j]) {
			return false
		}
		i++
		j++
	}
	return j == len(segs)
}

// globMatch implements a gitignore style glob for a single path component.
func globMatch(pat, s string) bool {
	return globMatchAt(pat, 0, s, 0)
}

func globMatchAt(p string, pi int, s string, si int) bool {
	for pi < len(p) {
		c := p[pi]
		switch c {
		case '*':
			double := pi+1 < len(p) && p[pi+1] == '*'
			if double {
				// ** matches anything including separators; here we only need
				// the single segment case.
				npi := pi + 2
				if npi < len(p) && p[npi] == '/' {
					npi++
				}
				for k := si; k <= len(s); k++ {
					if globMatchAt(p, npi, s, k) {
						return true
					}
				}
				return false
			}
			npi := pi + 1
			for k := si; k <= len(s); k++ {
				if globMatchAt(p, npi, s, k) {
					return true
				}
			}
			return false
		case '?':
			if si >= len(s) {
				return false
			}
			pi++
			si++
		case '[':
			end := pi + 1
			if end < len(p) && (p[end] == '!' || p[end] == '^') {
				end++
			}
			if end < len(p) && p[end] == ']' {
				end++
			}
			for end < len(p) && p[end] != ']' {
				end++
			}
			if end >= len(p) {
				if si >= len(s) || s[si] != '[' {
					return false
				}
				pi++
				si++
				continue
			}
			if si >= len(s) || !matchClass(p[pi+1:end], s[si]) {
				return false
			}
			pi = end + 1
			si++
		case '\\':
			if pi+1 < len(p) {
				if si >= len(s) || s[si] != p[pi+1] {
					return false
				}
				pi += 2
				si++
				continue
			}
			if si >= len(s) || s[si] != '\\' {
				return false
			}
			pi++
			si++
		default:
			if si >= len(s) || s[si] != c {
				return false
			}
			pi++
			si++
		}
	}
	return si == len(s)
}

func matchClass(cls string, c byte) bool {
	neg := false
	i := 0
	if i < len(cls) && (cls[i] == '!' || cls[i] == '^') {
		neg = true
		i++
	}
	found := false
	for i < len(cls) {
		if i+2 < len(cls) && cls[i+1] == '-' {
			if c >= cls[i] && c <= cls[i+2] {
				found = true
			}
			i += 3
			continue
		}
		if cls[i] == c {
			found = true
		}
		i++
	}
	if neg {
		return !found
	}
	return found
}

// IsIgnoredFile reports whether a relative path should be skipped.
func (il *IgnoreList) IsIgnoredFile(path string, dirMode bool) bool {
	ignored := false
	for _, p := range il.patterns {
		if p.matchesPath(path, dirMode) {
			ignored = !p.negated
		}
	}
	return ignored
}

// IsIgnoredSecret reports whether a matched secret value is skipped.
func (il *IgnoreList) IsIgnoredSecret(s string) bool {
	if il == nil {
		return false
	}
	_, ok := il.secrets[s]
	return ok
}
GOEOF
echo ok"}

