package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

const (
	exitOK          = 0
	exitSecretFound = 1
	exitError       = 2
)

// entropyThreshold is the shannon entropy value a captured group must exceed
// before it is reported as a secret.
const entropyThreshold = 3.0

// maxFileSize limits how much of a file is scanned.
const maxFileSize = 10 << 20 // 10 MiB

type cli struct {
	installPreCommit bool
	strictIgnore     bool
	onlyMatching     bool
	additional       []string
	paths            []string
}

func main() {
	os.Exit(run())
}

func run() int {
	c, err := parseArgs(os.Args[1:])
	if err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		return exitError
	}
	if c.installPreCommit {
		return installPreCommit(c)
	}
	pats := []string{Pattern}
	pats = append(pats, c.additional...)
	var res []*regexp.Regexp
	for _, p := range pats {
		re, cerr := regexp.Compile(`(?m)` + p)
		if cerr != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", cerr)
			return exitError
		}
		res = append(res, re)
	}
	ign := loadSecretsIgnore(".")
	scanner := &fileScanner{
		res:        res,
		ignore:     ign,
		onlyMatch:  c.onlyMatching,
		strict:     c.strictIgnore,
		found:      false,
		reports:    map[string]struct{}{},
		exact:      c.paths != nil,
		additional: len(c.additional) > 0,
	}
	paths := c.paths
	if len(paths) == 0 {
		paths = []string{"."}
	}
	for _, p := range paths {
		scanner.walk(p, "", 0)
	}
	if scanner.found {
		return exitSecretFound
	}
	return exitOK
}

func parseArgs(args []string) (*cli, error) {
	c := &cli{}
	i := 0
	for i < len(args) {
		a := args[i]
		switch {
		case a == "-h" || a == "--help":
			fmt.Print(shortHelp())
			os.Exit(exitOK)
		case a == "--help":
			fmt.Print(longHelp())
			os.Exit(exitOK)
		case a == "-V" || a == "--version":
			fmt.Println("ripsecrets 0.1.11")
			os.Exit(exitOK)
		case a == "--install-pre-commit":
			c.installPreCommit = true
		case a == "--strict-ignore":
			c.strictIgnore = true
		case a == "--only-matching":
			c.onlyMatching = true
		case a == "--additional-pattern":
			if i+1 >= len(args) {
				return nil, fmt.Errorf("error: a value is required for '--additional-pattern <ADDITIONAL_PATTERNS>' but none was supplied")
			}
			i++
			c.additional = append(c.additional, args[i])
		case strings.HasPrefix(a, "--additional-pattern="):
			c.additional = append(c.additional, strings.TrimPrefix(a, "--additional-pattern="))
		case a == "--":
			c.paths = append(c.paths, args[i+1:]...)
			return c, nil
		case strings.HasPrefix(a, "-") && a != "-":
			return nil, fmt.Errorf("error: unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'\n\nUsage: %s [OPTIONS] [Source files]...\n\nFor more information, try '--help'.\n", a, a, a, progName())
		default:
			c.paths = append(c.paths, a)
		}
		i++
	}
	return c, nil
}

func progName() string {
	b := filepath.Base(os.Args[0])
	if b == "" {
		return "ripsecrets"
	}
	return b
}

func installPreCommit(c *cli) int {
	dir := "."
	if len(c.paths) > 0 {
		dir = c.paths[0]
	}
	gitDir := filepath.Join(dir, ".git")
	if st, err := os.Stat(gitDir); err != nil || !st.IsDir() {
		fmt.Fprintln(os.Stderr, "Error: .git directory not found")
		return exitError
	}
	hooks := filepath.Join(gitDir, "hooks")
	if err := os.MkdirAll(hooks, 0o755); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return exitError
	}
	pre := filepath.Join(hooks, "pre-commit")
	if _, err := os.Stat(pre); err == nil {
		fmt.Fprintln(os.Stderr, "Error: pre-commit hook has already been installed")
		return exitError
	}
	content := "ripsecrets --strict-ignore `git diff --cached --name-only --diff-filter=ACM`\n"
	if err := os.WriteFile(pre, []byte(content), 0o744); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return exitError
	}
	return exitOK
}

// loadSecretsIgnore reads the .secretsignore file in dir if it exists.
func loadSecretsIgnore(dir string) *IgnoreList {
	data, err := os.ReadFile(filepath.Join(dir, ".secretsignore"))
	if err != nil {
		return &IgnoreList{secrets: map[string]struct{}{}}
	}
	return ParseIgnoreList(string(data))
}

type fileScanner struct {
	res        []*regexp.Regexp
	ignore     *IgnoreList
	onlyMatch  bool
	strict     bool
	found      bool
	reports    map[string]struct{}
	exact      bool
	additional bool
}

// walk visits a path. rel is the path relative to the scan root.
func (s *fileScanner) walk(p, rel string, depth int) {
	st, err := os.Lstat(p)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s: %v\n", p, err)
		return
	}
	if rel == "" {
		rel = filepath.Base(p)
		if p == "." {
			rel = ""
		}
	}
	if st.IsDir() {
		if rel != "" && s.shouldSkipDir(rel) {
			return
		}
		entries, err := os.ReadDir(p)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s: %v\n", p, err)
			return
		}
		sort.Slice(entries, func(i, j int) bool { return entries[i].Name() < entries[j].Name() })
		for _, e := range entries {
			child := filepath.Join(p, e.Name())
			childRel := e.Name()
			if rel != "" {
				childRel = rel + "/" + e.Name()
			}
			s.walk(child, childRel, depth+1)
		}
		return
	}
	if rel == "" || rel == "." {
		rel = filepath.Base(p)
	}
	if s.shouldSkipFile(rel) {
		return
	}
	s.scanFile(p, rel)
}

func (s *fileScanner) shouldSkipDir(rel string) bool {
	base := filepath.Base(rel)
	if strings.HasPrefix(base, ".") && base != "." && base != ".." {
		return true
	}
	if s.ignore != nil && s.ignore.IsIgnoredFile(rel, true) {
		return true
	}
	return false
}

func (s *fileScanner) shouldSkipFile(rel string) bool {
	base := filepath.Base(rel)
	if strings.HasPrefix(base, ".") {
		return true
	}
	if s.ignore != nil && s.ignore.IsIgnoredFile(rel, false) {
		return true
	}
	return false
}

// scanFile reads a file and reports secrets found in it.
func (s *fileScanner) scanFile(path, rel string) {
	data, err := os.ReadFile(path)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s: %v\n", rel, err)
		return
	}
	if len(data) > maxFileSize {
		data = data[:maxFileSize]
	}
	if !utf8Like(data) {
		return
	}
	content := string(data)
	lines := splitLines(content)
	prefix := rel
	for _, re := range s.res {
		for _, loc := range re.FindAllStringSubmatchIndex(content, -1) {
			var secret string
			if len(loc) > 3 && loc[2] >= 0 {
				secret = content[loc[2]:loc[3]]
			} else {
				secret = content[loc[0]:loc[1]]
			}
			if secret == "" {
				continue
			}
			if s.ignore != nil && s.ignore.IsIgnoredSecret(secret) {
				continue
			}
			if len(loc) > 3 && loc[2] >= 0 {
				if shannonEntropy(secret) <= entropyThreshold {
					continue
				}
			}
			lineNo := lineOfOffset(content, loc[0], lines)
			display := secret
			if !s.onlyMatch {
				if lineNo-1 < len(lines) {
					display = lines[lineNo-1]
				} else {
					display = lineAt(content, loc[0])
				}
			}
			key := fmt.Sprintf("%s:%d:%s", rel, lineNo, display)
			if _, dup := s.reports[key]; dup {
				continue
			}
			s.reports[key] = struct{}{}
			fmt.Printf("%s:%d:%s\n", rel, lineNo, display)
			s.found = true
		}
	}
	_ = prefix
}

// utf8Like reports whether the data looks like valid UTF-8 text.
func utf8Like(data []byte) bool {
	return utf8Valid(data)
}

func splitLines(s string) []string {
	s = strings.TrimSuffix(s, "\n")
	if s == "" {
		return []string{}
	}
	return strings.Split(s, "\n")
}

// lineOfOffset converts a byte offset into a 1-based line number.
func lineOfOffset(content string, off int, lines []string) int {
	pos := 0
	for i, l := range lines {
		end := pos + len(l)
		if off <= end {
			return i + 1
		}
		pos = end + 1
	}
	return len(lines)
}

func lineAt(content string, off int) string {
	start := off
	for start > 0 && content[start-1] != '\n' {
		start--
	}
