		switch {
		case a == "-h" || a == "--help":
			fmt.Print(shortHelp())
			os.Exit(exitOK)
		case a == "--help":
			fmt.Print(longHelp())
			os.Exit(exitOK)
		case a == "-V" || a == "--version":
