type fileScanner struct {
	res        []*regexp.Regexp
	ignore     *IgnoreList
	onlyMatch  bool
	strict     bool
	found      bool
	reports    map[string]struct{}
	exact      bool
	additional bool
}

// walk visits a path. rel is the path relative to the scan root.
func (s *fileScanner) walk(p, rel string, depth int) {
	st, err := os.Lstat(p)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s: %v\n", p, err)
		return
	}
	if rel == "" {
		rel = filepath.Base(p)
		if p == "." {
			rel = ""
		}
	}
	if st.IsDir() {
		if rel != "" && s.shouldSkipDir(rel) {
			return
		}
		entries, err := os.ReadDir(p)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s: %v\n", p, err)
			return
		}
		sort.Slice(entries, func(i, j int) bool { return entries[i].Name() < entries[j].Name() })
		for _, e := range entries {
			child := filepath.Join(p, e.Name())
			childRel := e.Name()
			if rel != "" {
				childRel = rel + "/" + e.Name()
			}
			s.walk(child, childRel, depth+1)
		}
		return
	}
	if rel == "" || rel == "." {
		rel = filepath.Base(p)
	}
	if s.shouldSkipFile(rel) {
		return
	}
	s.scanFile(p, rel)
