// utf8Like reports whether the data looks like valid UTF-8 text.
func utf8Like(data []byte) bool {
	return utf8Valid(data)
}

func splitLines(s string) []string {
	s = strings.TrimSuffix(s, "\n")
	if s == "" {
		return []string{}
	}
	return strings.Split(s, "\n")
}

// lineOfOffset converts a byte offset into a 1-based line number.
func lineOfOffset(content string, off int, lines []string) int {
	pos := 0
	for i, l := range lines {
		end := pos + len(l)
		if off <= end {
			return i + 1
		}
		pos = end + 1
	}
	return len(lines)
}

func lineAt(content string, off int) string {
	start := off
	for start > 0 && content[start-1] != '\n' {
		start--
	}
	end := off
	for end < len(content) && content[end] != '\n' {
		end++
	}
	return content[start:end]
}

// shannonEntropy computes the Shannon entropy of a string in bits.
func shannonEntropy(s string) float64 {
	if s == "" {
		return 0
	}
	freq := make(map[rune]int, len(s))
	total := 0
	for _, c := range s {
		freq[c]++
		total++
	}
	var e float64
	for _, n := range freq {
		p := float64(n) / float64(total)
		e -= p * math.Log2(p)
	}
	return e
}
