// utf8Valid reports whether data decodes as valid UTF-8.
func utf8Valid(data []byte) bool {
	for i := 0; i < len(data); {
		c := data[i]
		if c < 0x80 {
			i++
			continue
		}
		n, err := utf8Len(c)
		if err != nil {
			return false
		}
		if i+n > len(data) {
			return false
		}
		for k := 1; k < n; k++ {
