			}
		}
		if !validRune(data[i:i+n]) {
			return false
		}
		i += n
	}
	return true
}

func utf8Len(c byte) (int, error) {
	switch {
	case c&0xE0 == 0xC0:
		return 2, nil
	case c&0xF0 == 0xE0:
		return 3, nil
	case c&0xF8 == 0xF0:
		return 4, nil
	}
	return 0, errInvalidUTF
}

type utf8Err struct{}

func (utf8Err) Error() string { return "invalid utf-8" }

var errInvalidUTF = utf8Err{}

func validRune(b []byte) bool {
	if len(b) == 2 {
		return true
	}
	// Reject overlong encodings and surrogates.
	if len(b) == 3 {
		if b[0] == 0xE0 && b[1] < 0xA0 {
			return false
		}
		if b[0] == 0xED && b[1] >= 0xA0 {
			return false
		}
		return true
	}
	if len(b) == 4 {
		if b[0] == 0xF0 && b[1] < 0x90 {
			return false
		}
		if b[0] == 0xF4 && b[1] > 0x8F {
			return false
		}
