best=None
for tu in [x/200 for x in range(80,140)]:
    for th in [x/100 for x in range(200,450,2)]:
        m=sum(1 for i,(n,u,h,v) in enumerate(rows) if ((u/n>tu) and (h>th))!=lab[i])
