    for th in [x/50 for x in range(100,400)]:
        m=sum(1 for i,(n,u,h,v) in enumerate(rows) if (h + c*u/n > th)!=lab[i])
        if best2 is None or m<best2[0]: best2=(m,c,th)
print("best H+c*ur:",best2)
